pub trait Letter { fn draw(&self) -> String; fn clone_letter(&self) -> Box<dyn Letter>; }

pub struct Envelope(Box<dyn Letter>);        // the envelope

impl Envelope {
    pub fn new(letter: impl Letter + 'static) -> Self { Self(Box::new(letter)) }
    pub fn draw(&self) -> String { self.0.draw() }          // explicit forwarding
}
impl Clone for Envelope {
    fn clone(&self) -> Self { Self(self.0.clone_letter()) } // deep copy
}
